import React, { useEffect, useState } from "react";
import Swal from "sweetalert2";
import { Pencil, Plus, Trash2 } from "lucide-react";
import { DashboardLayout } from "../components/layout/DashboardLayout";
import { Button } from "../components/ui/button";
import { useAuth } from "../contexts/AuthContext";
import companyService from "../services/company.service";
import CompaniesFormModal from "../components/companies/CompaniesFormModal";

export const CompaniesPage = () => {
  const { hasPermission } = useAuth();
  const canManage = hasPermission("companies.manage");
    const [companies, setCompanies] = useState([]);
    const [loading, setLoading] = useState(true);

    const loadCompanies = async () => {
        setLoading(true);
        try {
            const data = await companyService.getCompanies();
            setCompanies(data);
        } catch (error) {
            Swal.fire({
                icon: "error",
                title: "No se pudieron cargar las empresas",
                text: error.response?.data?.detail || "Intenta nuevamente",
                confirmButtonColor: "#16a34a",
            });
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadCompanies();
    }, []);
}
const openCreateModal = () => {
    // Implementar lógica para abrir modal de creación
    setEditingCompany(null);
    setModalOpen(true);
  };
  const openEditModal = (company) => {
    setEditingCompany(company);
    setModalOpen(true);
  };
const handleDelete = async (company) => {
    const result = await Swal.fire({
      icon: "warning",
        title: `¿Eliminar la empresa "${company.name}"?`,
        text: "Esta acción no se puede deshacer.",
        showCancelButton: true,
        confirmButtonColor: "#16a34a",
        cancelButtonColor: "#d33",
        confirmButtonText: "Sí, eliminar",
        cancelButtonText: "Cancelar",
    });
    if (result.isConfirmed) {
        try {            await companyService.deleteCompany(company.id);
            Swal.fire({
                icon: "success",
                title: "Empresa eliminada",
                confirmButtonColor: "#16a34a",
            });
            loadCompanies();
        } catch (error) {
            Swal.fire({
                icon: "error",
                title: "Error",
                text: error.response?.data?.detail || "Intenta nuevamente",
                confirmButtonColor: "#16a34a",
            });
        }
    }
    return (
        <DashboardLayout>
            <div className="flex items-center justify-between mb-4">
                <h1 className="text-2xl font-bold">Empresas</h1>
                {canManage && (
                    <Button onClick={openCreateModal}>
                        <Plus size={16} />
                        Crear empresa
                    </Button>
                )}
            </div>
            <div className="bg-white shadow rounded-lg">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider"> Nombre</th>
                            {canManage && <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Acciones</th>}
                        </tr> 
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                        {loading ? (
                            <tr>
                                <td colSpan={canManage ? 2 : 1} className="px-6 py-4 whitespace-nowrap text-center">
                                    Cargando...
                                </td>
                            </tr>
                        ) : companies.length > 0 ? (
                            companies.map((company) => (
                                <tr key={company.id}>
                                    <td className="px-6 py-4 whitespace-nowrap">{company.name}</td>
                                    {canManage && (
                                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                            <Button variant="outline" onClick={() => openEditModal(company)} className="mr-2">
                                                <Pencil size={16} />
                                            </Button>
                                            <Button variant="outline" color="destructive" onClick={() => handleDelete(company)}>
                                                <Trash2 size={16} />
                                            </Button>
                                        </td> 
                                    )}
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan={canManage ? 2 : 1} className="px-6 py-4 whitespace-nowrap text-center">
                                    No hay empresas registradas.
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
            {/* Aquí iría el CompaniesFormModal para crear/editar empresas */}
            <CompaniesFormModal
                open={modalOpen}
                onOpenChange={setModalOpen}
                onSuccess={loadCompanies}
                company={editingCompany}
            />
        </DashboardLayout>
    );
};

export default CompaniesPage;
